<?php
$pageTitle='Detail Transfer';
ob_start();
if(empty($_SESSION['csrf_token'])) $_SESSION['csrf_token']=bin2hex(random_bytes(32));
$dispatchPhotos=array_values(array_filter($attachments??[],fn($a)=>$a['reference_type']==='transfer_dispatch'));
$receivePhotos=array_values(array_filter($attachments??[],fn($a)=>$a['reference_type']==='transfer_receive'));
$canReceive=in_array($transfer['status'],['IN_TRANSIT','PARTIAL_RECEIVED'],true) && !\App\Helpers\AuthHelper::hasRole('SUPERADMIN');
$pdoDoc=\App\Core\Database::getInstance()->getConnection();
$serialMap=[];
$serialStmt=$pdoDoc->prepare("SELECT tis.transfer_item_id, sn.serial_number, tis.status FROM transfer_item_serials tis JOIN serial_numbers sn ON sn.id=tis.serial_number_id WHERE tis.transfer_item_id IN (SELECT id FROM transfer_items WHERE transfer_id=?) ORDER BY tis.id");
$serialStmt->execute([(int)$transfer['id']]);
foreach($serialStmt->fetchAll(PDO::FETCH_ASSOC) as $snRow){$serialMap[(int)$snRow['transfer_item_id']][]=$snRow;}
$totalSent=0;$totalReceived=0;$serializedLines=0;
foreach($items as $it){$totalSent+=(int)$it['quantity_sent'];$totalReceived+=(int)$it['quantity_received'];if((int)$it['is_serialized']===1)$serializedLines++;}
$progress=$totalSent>0?min(100,round(($totalReceived/$totalSent)*100)):0;
$suratJalanCode='SJ-'.$transfer['transaction_code'];
?>
