            <div class="space-y-3"><?php foreach($items as $item): $remaining=(int)$item['quantity_sent']-(int)$item['quantity_received']; $itemProgress=(int)$item['quantity_sent']>0?min(100,round(((int)$item['quantity_received']/(int)$item['quantity_sent'])*100)):0; ?><div class="rounded-2xl border border-gray-200 bg-gray-50 p-4 dark:border-gray-700 dark:bg-gray-900/30"><div class="flex flex-col gap-3 md:flex-row md:items-start md:justify-between"><div><div class="font-semibold text-gray-900 dark:text-gray-100"><?=htmlspecialchars($item['nama'])?></div><div class="mt-1 text-xs text-gray-500 dark:text-gray-400"><?=htmlspecialchars($item['kode_barang'])?> · <?=$item['is_serialized']?'Pakai Nomor Seri':'Tanpa Nomor Seri'?></div></div><div class="text-right"><div class="text-lg font-bold text-gray-900 dark:text-gray-100"><?=number_format($item['quantity_received'])?> / <?=number_format($item['quantity_sent'])?></div><div class="text-xs text-gray-500">diterima</div></div></div><div class="mt-3 h-2 overflow-hidden rounded-full bg-gray-200 dark:bg-gray-700"><div class="h-full rounded-full bg-blue-600" style="width:<?=$itemProgress?>%"></div></div><?php if($item['is_serialized']): ?><details class="mt-3"><summary class="cursor-pointer text-xs font-semibold text-blue-600 dark:text-blue-300">Lihat nomor seri (<?=count($serialMap[(int)$item['id']]??[])?>)</summary><div class="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-4"><?php foreach(($serialMap[(int)$item['id']]??[]) as $sn): ?><span class="rounded-lg border border-gray-200 bg-white px-2.5 py-2 text-xs font-medium text-gray-700 dark:border-gray-700 dark:bg-gray-800 dark:text-gray-200"><?=htmlspecialchars($sn['serial_number'])?></span><?php endforeach; ?></div></details><?php endif; ?><?php if($remaining>0): ?><div class="mt-3 text-xs font-semibold text-orange-600">Sisa yang belum diterima: <?=number_format($remaining)?></div><?php else: ?><div class="mt-3 text-xs font-semibold text-green-600">✓ Barang ini sudah